ATCCardsData("OM08",[["pw0rov","En el manual de ENAIRE, ¿cómo define el Doc. 10151 de la OACI las actuaciones humanas (*human performance*)?","Cómo llevan a cabo las personas sus actividades; representan la contribución humana al funcionamiento del sistema."],["1b1kiud","En el manual de ENAIRE, ¿cómo define el Doc. 10151 de la OACI los factores humanos (*human factors*)?","La aplicación del conocimiento sobre los seres humanos, sus capacidades, características y limitaciones al diseño de los equipos que utilizan, los entornos en los que operan y las actividades que realizan."],["1xxzhd6","Fuera de la aviación, ¿con qué aspectos se asocian, respectivamente, los factores humanos y la ergonomía?","Factores humanos: más con los aspectos psicológicos. Ergonomía: más con los aspectos físicos o fisiológicos."],["ihxdpu","Cita cuatro disciplinas de las que los factores humanos obtienen su comprensión de las actuaciones humanas.","Por ejemplo: psicología (cognitiva, organizacional y del trabajo, social), psicología conductual, sociología, antropología, ciencias médicas (medicina de aviación y ocupacional), diseño e ingeniería, informática, estadística."],["bx950r","¿Por qué es esencial el estudio de los factores humanos en ATM (manual 1.1)?","Para saber si el diseño de la tecnología, la selección del personal, la formación, los procedimientos, los roles, tareas y responsabilidades y la gestión de la organización garantizan un rendimiento óptimo del sistema y una gestión eficaz del riesgo."],["1nyhlfg","¿Cuándo presentó James Reason su visión sistémica de la gestión de la seguridad (manual 1.2.1)?","A mediados de la década de 1990 («a mediados de 1990»)."],["yr14gf","Según la visión de Reason, ¿de qué son resultado los accidentes?","De la acción humana combinada con otros fallos del sistema (no del error individual por sí solo)."],["1k9cd7g","¿Qué concepto introdujo el modelo del queso suizo en cualquier industria?","El accidente organizacional: el impacto de la cultura y las políticas de la organización sobre los controles de riesgo para la seguridad."],["1wphrs","En el modelo del queso suizo, ¿qué representan las lonchas y los agujeros, y cuándo ocurre el suceso?","Lonchas = capas de protección; agujeros = sus debilidades; el suceso ocurre cuando los agujeros se alinean."],["13aecva","En el modelo del queso suizo, ¿qué crean los factores organizacionales que puede hacer fallar las defensas?","Condiciones latentes."],["504iu4","Según el manual, ¿cuál fue la mayor contribución de Reason, y la menos conocida?","Su investigación sobre los errores humanos, de la que salió el modelo de clasificación GEMS (Sistema General de Modelado de Errores, *General Error Modelling System*)."],["xmriug","¿Qué estudió Reason sobre las actuaciones sobresalientes?","Qué hace que los sistemas funcionen correctamente y qué permite que las personas salven a veces situaciones críticas."],["16stwqa","¿El modelo de qué autor explica el comportamiento mediante tres modos de desempeño (habilidades, reglas, conocimiento)?","Rasmussen."],["18f2kl0","Rasmussen: conducta basada en habilidades (*skill-based*)","Acciones no realizadas de forma consciente; control cognitivo automatizado; tarea rutinaria muy conocida (p. ej., conducir siendo un conductor experimentado)."],["1f1ug1f","Rasmussen: conducta basada en reglas (*rule-based*)","Procesos de decisión conscientes para elegir qué reglas aplicar; situaciones conocidas pero poco frecuentes (p. ej., aplicar los procedimientos operativos en frecuencia)."],["gnb5k6","Rasmussen: conducta basada en conocimiento (*knowledge-based*)","No hay reglas ni secuencias almacenadas; gran esfuerzo consciente para analizar y elegir entre alternativas; aprendizaje de habilidades nuevas, situaciones de emergencia o inusuales."],["1lju47n","¿Qué modo de Rasmussen asocia el manual con una emergencia o una situación inusual en frecuencia?","La conducta basada en conocimiento."],["8sub13","¿Qué circular de la OACI propuso formalmente el modelo SHELL como modelo conceptual de FFHH (manual)?","La Circular 216-AN31."],["1ntxoim","¿Quién y cuándo creó el modelo SHELL según el manual?","Edwards 1972, Hawkins 1993."],["xas27","¿Qué añade la versión actualizada SHELL-O?","Organización: los factores organizacionales como parte del sistema."],["7mqupe","SHELL-O: ¿qué significa cada letra (con el español del manual)?","S *Software* (soporte lógico, procedimientos); H *Hardware* (soporte físico, sistemas técnicos); E *Environment* (entorno); L *Liveware* (elemento humano); O *Organization* (organización)."],["ow1sbh","En SHELL-O, ¿qué componente es el centro y el más flexible?","El ser humano, *Liveware* (L); los demás componentes deben ajustarse a él."],["ju6fzk","¿A qué operadores de primera línea puede representar la L de SHELL-O (manual)?","Al controlador de tránsito aéreo, al ATSEP y al piloto."],["3ndlj4","SHELL-O: interfaz L-S","Relación entre el controlador y todos los sistemas de apoyo: reglamentos, manuales, listas de comprobación, procedimientos normalizados de operación."],["b52v9d","SHELL-O: interfaz L-H","Interfaz ser humano-máquina: si el diseño del equipo se adapta a la persona (consolas, pantallas, alarmas, ergonomía)."],["9r4usi","SHELL-O: interfaz L-E","Persona y entorno de trabajo, interno (temperatura, ruido, clima laboral) y externo (p. ej., meteorología)."],["c91a19","SHELL-O: interfaz L-L","Persona y las demás personas en el trabajo: liderazgo, cooperación, trabajo en equipo (TRM), relaciones entre operación y dirección, cultura de la empresa."],["1hm98lz","¿Por qué la letra O tiene más peso en SHELL-O?","Los factores organizacionales tienen mayor peso específico: las políticas sobre cómo se gestionan los procedimientos y los cambios, los sistemas técnicos y las personas."],["19a4skb","¿Qué son los factores psicosociales en el manual?","Factores externos del sistema social de la persona, dentro y fuera del trabajo, que añaden presión e influyen en su enfoque personal del trabajo y en su capacidad para afrontar el estrés y las situaciones anormales (OACI 2002)."],["fpmhm9","Cita cuatro factores físicos o fisiológicos que afectan a las actuaciones humanas (manual 1.2.3).","Visión, audición, luz, ruido, estrés, ritmos circadianos."],["18tpqjn","Cita cuatro factores psicológicos que afectan a las actuaciones humanas (manual 1.2.3).","Conocimientos y experiencia, idoneidad de la formación, motivación, confianza, toma de decisiones, fatiga, carga de trabajo, trabajo en equipo."],["i0i6y","Enumera los ocho factores organizacionales del comienzo de la sección 1.3 del manual.","1 adecuación de los recursos humanos; 2 selección de personal idóneo; 3 formación recibida; 4 atención al bienestar de los profesionales; 5 eficiencia de la empresa en la gestión de procesos y proyectos; 6 planificación y organización del personal; 7 gestión del riesgo; 8 cultura organizacional y comunicación."],["1agf3jb","¿Por qué es la aviación un sistema sociotécnico complejo?","Es de gran tamaño y alta tecnología y requiere interacciones complejas entre componentes humanos y tecnológicos."],["6wq9sy","¿Qué implica la complejidad para el comportamiento de un sistema sociotécnico?","Incertidumbre en las interacciones internas: el comportamiento es no lineal y en parte impredecible; pero también le da una gran capacidad de adaptación."],["1x1bn6u","¿Qué componente del sistema es el más flexible, adaptable y valioso, pero también el más vulnerable?","El ser humano."],["1sq0do2","Según el manual, ¿qué debería ser la expresión «error humano»?","Un punto de partida que indica dónde falló el sistema, no una explicación."],["ihrdvr","¿Por qué el manual llama al «error humano» una construcción social?","Porque una instrucción errónea corregida a tiempo rara vez se llama error, aunque no se diferencie de otra que acaba en incidente: la etiqueta depende de las consecuencias más que de la acción."],["6z23my","Según el manual, ¿de qué heredan sus procesos las metodologías actuales de investigación?","De los procedimientos de investigación criminal surgidos a principios del siglo XX."],["dq7iuk","¿Qué documento de la OACI adoptó formalmente el enfoque sistémico en la investigación de sucesos, y en qué año?","El Anexo 13, en 1994."],["1363yr6","Visión contemporánea de la seguridad: ¿cómo se considera todo accidente o incidente?","Como un fallo del sistema, no solo de una persona o un grupo, porque las actuaciones humanas no se dan en el vacío."],["yhnduw","¿Quién propuso los diez principios del pensamiento sistémico para la seguridad (*Systems Thinking for Safety*), y cuándo?","EUROCONTROL, 2014."],["zoq1c5","Principio sistémico 1 de EUROCONTROL","Implicación de los expertos en la materia."],["rrsyeu","Principio sistémico 2 de EUROCONTROL","Racionalidad local."],["8k9yu3","Principio sistémico 3 de EUROCONTROL","Cultura justa."],["v4ngdo","Principio sistémico 4 de EUROCONTROL","Demanda y presión."],["1260rjl","Principio sistémico 5 de EUROCONTROL","Recursos y limitaciones."],["7e4u9e","Principio sistémico 6 de EUROCONTROL","Interacciones y flujos."],["624253","Principio sistémico 7 de EUROCONTROL","Contrapartidas (*trade-offs*)."],["j8jsxk","Principio sistémico 8 de EUROCONTROL","Variabilidad del rendimiento."],["mcs94t","Principio sistémico 9 de EUROCONTROL","Emergencia del sistema."],["p8xwa5","Principio sistémico 10 de EUROCONTROL","Equivalencia."],["1jy1l2p","¿Qué principio de EUROCONTROL dice que la contribución de cada experto debe entenderse desde sus propios objetivos, limitaciones y contexto?","El principio 2, racionalidad local."],["1slm8uu","¿Qué principio dice que el éxito y el fracaso se originan en los mismos procesos?","El principio 10, equivalencia."],["191el4t","¿Qué principio dice que una acción pequeña puede tener grandes efectos y que los resultados pueden ser inesperados?","El principio 9, emergencia del sistema."],["11dy3vc","¿Qué principio implica que los profesionales equilibran eficiencia y precisión?","El principio 7, contrapartidas."],["x7pk7s","¿Qué principio dice que entender la demanda es crucial y que el par demanda-presión afecta al rendimiento?","El principio 4, demanda y presión."],["1nw04xi","¿Qué principio pide gestionar los flujos «de extremo a extremo» y entender las interacciones?","El principio 6, interacciones y flujos."],["1drocxa","¿Qué principio pide identificar la variabilidad deseada y la no deseada?","El principio 8, variabilidad del rendimiento."],["1xsig0q","¿Qué principio implica una mentalidad abierta, justa y de confianza y un lenguaje que evite los juicios de valor?","El principio 3, cultura justa."],["1og1mrx","Safety-I: definición de seguridad","Que salgan mal las menos cosas posibles."],["13s3rj8","Safety-II: definición de seguridad","Que salgan bien las máximas cosas posibles."],["1p5wh87","Safety-I frente a Safety-II: principio de gestión de la seguridad","Safety-I es reactivo (se responde cuando ocurre algo o un riesgo es inaceptable); Safety-II es proactivo (se intenta anticipar los sucesos de forma continua)."],["ysfsd7","Safety-I frente a Safety-II: visión del ser humano","Safety-I: predominantemente una amenaza. Safety-II: un recurso necesario para la resiliencia y la flexibilidad del sistema."],["uept7k","Safety-II: finalidad de la investigación de accidentes","Entender cómo salen bien normalmente las cosas, como base para explicar cómo salen mal a veces."],["p8py0v","¿En qué décadas se desarrolló sobre todo Safety-I, y por qué?","Entre las décadas de 1960 y 1980, cuando la demanda de tráfico era menor y los sistemas, más simples e independientes."],["m3hicx","¿Qué año de publicación de EUROCONTROL se da para la tabla Safety-I frente a Safety-II?","2013."],["xaj7x5","Rasmussen (1985, 1986): ¿de qué es resultado el error humano?","Del desequilibrio entre las demandas del trabajo y los recursos mentales disponibles para atenderlas; las raíces del éxito y del fracaso son las mismas."],["1xryvpj","¿Cómo llama Simon (1957) a los límites en las decisiones de los operadores debidos a la información, la capacidad mental y el tiempo limitados?","Racionalidad limitada."],["1khbsc3","¿Qué autor (2009) se cita a propósito de las contrapartidas de los controladores, p. ej., más seguro frente a más eficiente?","Hollnagel (2009), el principio ETTO."],["loth9e","Trabajo como se imagina (*Work-As-Imagined*, WAI) frente a trabajo como se hace (*Work-As-Done*, WAD)","WAI = cómo debería ocurrir el trabajo tal como se concibe y diseña; WAD = lo que ocurre realmente en el día a día."],["11s4514","¿Qué ejemplo da el manual de una brecha WAI/WAD en ATM?","La implantación prematura de nuevos sistemas: comportamientos inesperados y perturbaciones, que obligan a revisar la operación real en una fase táctica."],["28chim","Según Woods y Dekker (2002), ¿qué son los conceptos de diseño?","Solo hipótesis sobre la relación futura entre la tecnología y las personas; la automatización transforma la práctica diaria."],["10s9fcb","¿Cuántas variedades de trabajo añade Steven Shorrock, y cuáles son?","Ocho: trabajo prescrito, divulgado, analizado, observado, simulado, instruido, medido y juzgado."],["1wl2h1r","¿Qué reglamento fija requisitos comunes para los proveedores de ATM/ANS y otras funciones de la red de ATM?","El Reglamento de Ejecución (UE) 2017/373 de la Comisión, de 1 de marzo de 2017."],["jz02uz","¿En qué parte del Reglamento 2017/373 están los requisitos específicos de FFHH para los proveedores de ATC?","Anexo IV, sección 3."],["1tpgz5l","¿Qué regula ATS.OR.300?","El alcance: los requisitos de actuaciones humanas del proveedor para prevenir y limitar el uso problemático de sustancias psicoactivas, los efectos negativos del estrés y los efectos negativos de la fatiga en los controladores."],["1tp7ino","¿Qué regula ATS.OR.305?","Las responsabilidades de los proveedores de ATC sobre el uso problemático de sustancias psicoactivas por parte de los controladores."],["18t0coa","¿Quién debe aprobar el procedimiento para detectar el uso problemático de sustancias psicoactivas (ATS.OR.305)?","La autoridad competente."],["76hxt0","¿Qué punto de las licencias ATCO indica ATS.OR.305 que el proveedor debe tener en cuenta?","El punto ATCO.A.015 del Reglamento (UE) 2015/340."],["1j3lqrc","¿Qué características debe tener el procedimiento de detección de sustancias psicoactivas?","Objetivo, transparente y no discriminatorio."],["1obmpn2","¿Qué regula ATS.OR.310?","El estrés: una política de gestión del estrés que incluya un programa de gestión del estrés por incidente crítico, y programas de formación e información sobre la prevención del estrés."],["1ob4qjf","¿Qué regula ATS.OR.315?","La fatiga: una política de gestión de la fatiga y programas de información sobre su prevención."],["jrkvqb","¿Qué regula ATS.OR.320?","Los sistemas de turnos de los controladores: un sistema para gestionar el riesgo de fatiga ocupacional, que especifica ocho elementos, y la consulta a los controladores afectados o a sus representantes."],["1fww5k1","¿Qué dos disposiciones del Reglamento 2015/340 complementan los programas de información de ATS.OR.310 y ATS.OR.315?","La formación en FFHH de las secciones 3 y 4 de la subparte D del anexo I."],["vb7anp","ATS.OR.320: enumera los ocho elementos que debe especificar el sistema de turnos.","1 máximo de días laborables consecutivos; 2 máximo de horas por periodo de servicio; 3 duración máxima del control de tránsito aéreo sin pausas; 4 proporción entre periodos de servicio y pausas; 5 periodos mínimos de descanso; 6 máximo de periodos de servicio consecutivos que incluyan la noche; 7 periodos mínimos de descanso tras un servicio que incluya horas nocturnas; 8 periodos mínimos de descanso dentro del mismo ciclo de turnos."],["1v6trxc","ATS.OR.320: elemento 6","Número máximo de periodos de servicio consecutivos que incluyan la noche, en su caso, según las horas de funcionamiento de la dependencia."],["dqva4j","¿A quién hay que consultar al desarrollar el sistema de turnos (ATS.OR.320 b)?","A los controladores sujetos a él o, en su caso, a sus representantes."],["zywz5s","¿Qué reglamento, de 20 de febrero de 2015, fija los requisitos de las licencias ATCO y los conocimientos de FFHH que deben tener los controladores?","El Reglamento (UE) 2015/340 de la Comisión."],["ft5z4m","Formación básica en FFHH (2015/340): los cinco apartados del manual.","Introducción a los FFHH; actuaciones humanas; error humano; comunicación; entorno de trabajo."],["1u47p9n","¿Qué temas abarcan las «actuaciones humanas» en la formación básica (manual 1.5)?","Conducta individual, cultura de seguridad y conducta profesional, salud y bienestar, trabajo en equipo, necesidades humanas básicas en el trabajo, estrés."],["yaa1ls","Cursos de formación de habilitación: nombra los temas de FFHH del manual.","Factores psicológicos y cognitivos; factores médicos y fisiológicos (fatiga y aptitud); factores sociales y organizacionales (TRM, trabajo en equipo y roles, conducta responsable); estrés; error humano (errores y transgresiones); trabajo colaborativo (comunicación, trabajo en equipo, cooperación controlador/piloto)."],["1dpmzxv","Nombra cinco efectos sobre la organización si los FFHH no se gestionan bien (manual 1.6).","Compromiso de los empleados, rendimiento y productividad del personal, incidentes causados por error humano, absentismo, satisfacción del cliente, daño a la imagen y la reputación."],["hpg9q","Nombra los ámbitos en los que una integración eficaz de los FFHH tiene un impacto positivo y medible (manual 1.6).","Mejora de la seguridad, optimización de la organización y del personal, mejora de la capacidad y la eficiencia, reducción de costes, cumplimiento normativo."],["1n53xep","«El ser humano siempre es el porqué, y la tecnología el cómo»: ¿qué expresa?","Que en el sistema sociotécnico de ATM el ser humano es siempre el porqué y la tecnología, el cómo."],["behisu","¿Qué permite la integración de los FFHH en el SMS?","Identificar y entender la variabilidad del rendimiento (humano y del sistema), mejorar la investigación de sucesos, hacer más eficaces las recomendaciones de seguridad y aumentar los márgenes de seguridad."],["1t3j8pc","¿En qué clima notifican los controladores con confianza los incidentes de seguridad (manual 1.6)?","En un clima de cultura justa."],["l25jgn","¿Sobre qué premisa se desarrolló el concepto operativo básico de SESAR respecto a los FFHH?","Que el factor humano es un pilar fundamental en la operación de los futuros sistemas ATM."],["5pwk45","¿Qué porcentaje del coste final de un proyecto queda fijado en el primer 10 % de su ciclo de vida (EUROCONTROL-FAA 2010)?","Alrededor del 70 %."],["1q831xr","Da cuatro razones de negocio para detectar y vigilar el impacto de las acciones sobre los FFHH (manual 1.6).","Evitar daños; anticipar nuevos requisitos legislativos; evitar sanciones; favorecer la imagen pública e interna de la empresa."],["1bnrgeo","Definición de equipo en el manual","Un grupo de personas que interactúan de forma dinámica, son interdependientes y tienen un objetivo común, con tareas, funciones y roles diferentes."],["rkfzdn","Grupo frente a equipo: ¿cuál tiene un control externo elevado y limita la comunicación al superior inmediato?","El grupo."],["16e30ri","Grupo frente a equipo: ¿cuál actúa con gran autonomía, se preocupa por el resultado y el proceso y fomenta la comunicación abierta?","El equipo."],["zz3c1t","¿Qué elemento de los equipos avisa a los demás cuando se acerca un límite operativo o una persona se desvía?","El sistema de monitorización mutua."],["1e3lj5h","Comunicación ideal en el equipo según el manual","Comunicación constante en bucle cerrado de toda la información relevante, tanto al emitir como al escuchar."],["ekf80l","¿Qué significa TRM y de qué concepto deriva?","*Team Resource Management* (gestión de recursos de equipo); deriva del CRM (*Cockpit/Crew Resource Management*)."],["lzd1lx","Además de la aviación, ¿en qué campos se usa la terminología TRM (manual)?","Sanidad, energía nuclear y operaciones militares."],["9vclda","TRM como filosofía: ¿de qué reconocimiento surge?","De que los seres humanos son propensos a cometer errores y estos no pueden eliminarse del todo."],["1akrzhr","Enumera las seis categorías de habilidades TRM (en el orden del manual).","1 Trabajo en equipo; 2 gestión de roles en un equipo; 3 comunicación interpersonal; 4 conciencia situacional; 5 resolución de problemas y toma de decisiones; 6 gestión del estrés."],["1ltyiub","¿Las habilidades TRM son de naturaleza cognitiva o conductual?","Conductual: rastreables hasta aspectos concretos del funcionamiento humano."],["xa0rzn","¿Qué beneficio del TRM evita saturar la capacidad de una persona y produce redundancia?","El mejor uso de los recursos humanos mediante una distribución bien planificada de las cargas de trabajo y las responsabilidades."],["1ap7f4j","¿Cuánto tiempo retiene la información la memoria a corto plazo, según el manual?","De 20 a 30 segundos; funciona como la memoria de trabajo de un ordenador."],["1m5sxms","Capacidad de la memoria a largo plazo según el manual","Ilimitada, pero requiere más tiempo."],["1ffuj5n","¿Qué método para consolidar información en la memoria a largo plazo indica el manual?","El ensayo repetitivo de una actividad."],["o8ffsz","¿Qué construye los modelos mentales?","La formación, el aprendizaje y la experiencia, que almacenan patrones que forman representaciones de la realidad."],["1opmnrc","En la descripción del manual, ¿qué dos personas gestionan un sector radar?","Un controlador ejecutivo y un controlador planificador."],["7xumai","Funciones básicas del profesional del control de tránsito aéreo (manual 3.2)","Prevención de colisiones, supervisión del tráfico, gestión del espacio aéreo, comunicaciones y toma de decisiones."],["8kmwi6","Definición de conciencia situacional de Endsley","Percepción de los elementos del entorno dentro de un volumen de tiempo y espacio, comprensión de su significado y proyección de su estado en un futuro próximo."],["1vgr9mr","Los tres niveles de SA de Endsley","1 Percepción; 2 comprensión; 3 proyección."],["2pn3rz","¿Quién describe la SA como un estado o proceso que evalúa indicios pasados y presentes en una situación dinámica?","Isaac y Ruitenberg."],["1is220g","¿Cómo describen los controladores la SA de manera informal?","«Ver el tráfico» o «adelantarse al tráfico»."],["bpl0ru","¿Cómo expresan los controladores la dificultad para mantener la SA?","«Ir por detrás del tráfico» o «perder el control»."],["1c8nqum","Perder el control está directamente relacionado, en sucesos inesperados, con","La falta de tiempo, de conocimientos, de competencia y de recursos cognitivos."],["6994i3","¿Qué tres grupos de factores influyen en la SA según Endsley?","Factores individuales, factores ambientales y factores del sistema."],["1je1kza","Factores individuales que limitan la SA (Endsley)","Los límites que imponen la atención humana y la memoria de trabajo."],["7p33pb","Factores ambientales y del sistema que afectan a la SA (Endsley)","Factores estresantes físicos y psicológicos."],["1dt8rqm","¿Es la SA una instantánea? ¿Qué es, según el manual?","No: un modelo mental dinámico, un conjunto de procesos que dan forma a la información percibida hasta componer una imagen mental sobre la que se proyectan cursos de acción y estados futuros."],["p40v6u","¿Qué hace la mente cuando al modelo mental le falta información (visión TRM)?","Rellena los huecos haciendo asunciones basadas en la experiencia pasada o en lo más probable."],["1snmd17","¿Qué dos puntos vitales para la seguridad se derivan de las asunciones en la SA?","El equipo es también una fuente vital de información; y la mayoría de los incidentes de tránsito aéreo implican alguna asunción."],["1kwcmjx","Las tres dimensiones fundamentales de la carga de trabajo mental","1 Presión de tiempo de la tarea; 2 recursos de procesamiento cognitivo que exige la tarea; 3 aspectos emocionales."],["jagbw9","Definición de carga de trabajo mental (Sebastián y del Hoyo, 2002)","El conjunto de requerimientos mentales, cognitivos o intelectuales a los que se enfrenta el trabajador a lo largo de la jornada laboral, es decir, el nivel de esfuerzo intelectual necesario para realizar las tareas."],["62iz5u","¿Qué norma española da orientaciones para diseñar sistemas de trabajo frente al riesgo de carga de trabajo mental?","UNE-EN ISO 10075-2."],["131xem2","ISO 10075: presión mental frente a tensión mental","Presión mental = todas las influencias externas evaluables que afectan mentalmente a una persona; tensión mental = el efecto inmediato de la presión mental sobre el individuo."],["14jnxhh","Ley de Yerkes-Dodson","La relación entre estrés o activación y rendimiento tiene forma de U invertida: es óptima con una activación moderadamente alta y empeora si es demasiado alta o demasiado baja."],["1kmat2o","Yerkes-Dodson: tareas complejas frente a tareas simples","Con una tarea compleja el umbral de máximo rendimiento se alcanza antes que con una tarea simple."],["ny2ho4","¿Por qué una baja densidad de tráfico no es automáticamente inocua para los FFHH?","La vigilancia sostenida en la monitorización puede causar tanta fatiga como una carga de trabajo mental alta, o más."],["gq6p2l","Según el manual, ¿cuándo es probable que un controlador cometa un error o pase por alto un problema?","Tras gestionar un pico de tráfico («una vara de tráfico»), porque la atención sostenida satura los recursos mentales."],["2ehpf5","Opinión de consenso sobre complejidad, carga de trabajo y capacidad (manual 3.4)","La complejidad impulsa la carga de trabajo mental del controlador, que a su vez limita en última instancia la capacidad ATC."],["buck7b","Da seis factores que influyen en la complejidad del tráfico aéreo (manual 3.4).","Por ejemplo: complejidad del sector y flujos, áreas restringidas, volumen y tipo de tráfico (IFR/VFR, esperas, vectorización), conflictos, congestión de la frecuencia, emergencias, tiempo disponible, número de cartas de acuerdo, aeropuertos y fijos, meteorología, estado de los sistemas, coordinación, trabajo en equipo, herramientas de apoyo, experiencia del controlador, estrés y fatiga."],["1tqq161","¿Quiénes desarrollaron en 2013 una taxonomía de las estrategias de mitigación de la complejidad de los controladores?","Kontogiannis y Malakis."],["mn6v95","Tácticas de los controladores en la resolución de conflictos complejos (manual 3.4)","Soluciones que requieran menos coordinaciones; separación vertical para los conflictos más complejos; autorizaciones iniciales más «seguras» que se revisan después."],["oaprwe","Efecto de una alta complejidad en la calidad del servicio (manual)","La calidad del servicio se reduce en favor de más seguridad: se priorizan las tareas importantes, se simplifican los problemas y se anticipan las amenazas; pero esto requiere tiempo y aumenta la carga de trabajo, lo que facilita el error."],["dwdlx0","Bajo una presión extrema, el controlador tiende a","Actuar de la forma que normalmente funciona y a veces omitir acciones."],["8pcigo","Definición de comunicación en el manual","Proceso en el que un emisor transmite un mensaje, verbal o no verbal, a un receptor a través de un canal y con un código común a ambos, para difundir, intercambiar o compartir información, ideas o sentimientos."],["1260g75","Componentes de la comunicación en el manual","Emisor, receptor, mensaje, canal, mismo código, barreras; además de ruido y retroalimentación."],["u8tr7l","«Quien mejor se comunica es quien ...», y ¿quién es responsable de que el mensaje llegue?","Quien mejor escucha; quien se comunica es responsable de asegurarse de que el mensaje ha llegado correctamente."],["1x5gzd","Comunicación correcta pero no eficaz: ¿qué muestra el ejemplo del destornillador?","Que el ruido puede impedir que el receptor reaccione: el mensaje estaba bien expresado (correcto) pero no produjo la acción (no fue eficaz)."],["1htb1lr","¿Qué concepto vincula el manual con comprobar que la interferencia no reduce la ejecución del mensaje?","La «colación» (*read-back*)."],["185iy0q","Retroalimentación (*feedback*) en el manual","La respuesta del receptor a la información del emisor; no tiene por qué ser explícita: el silencio es en sí mismo un mensaje."],["1wwamds","Finalidad de la comunicación en las organizaciones (manual)","No que alguien te entienda, sino generar una acción común; es persuasiva."],["kziby4","¿Escuchar es una combinación de qué cinco actividades?","Oír; comprender los sonidos; comprender la interpretación; retener y recordar; actuar o responder de algún modo."],["1xukciq","Da tres factores que favorecen la escucha activa.","Mantener el contacto visual; hacer pequeños resúmenes de lo que el otro dice y siente; hacer preguntas abiertas."],["zdhb4k","Da tres factores que dificultan la escucha activa.","Lenguaje corporal inhibidor; abuso de distracciones; dejar temas a medias; interrupciones constantes; comentarios cortantes o gratuitos."],["16rk9au","Barreras ambientales a la comunicación: ejemplos","Incomodidad física (calor, silla incómoda), distracciones visuales, interrupciones y ruidos (timbre, teléfono, tos)."],["d12g0l","Tres tipos de barreras inherentes al ser humano","Cognitivas, fisiológicas y psicológicas."],["4bek5x","Barreras cognitivas: ejemplos","Barreras verbales (hablar rápido, lengua materna distinta); barreras semánticas; desconocimiento de procedimientos o términos; carga de trabajo/fatiga; pocas referencias sobre el receptor."],["oecdxf","Barreras fisiológicas: ejemplos","Emisor: voz débil, pronunciación defectuosa. Receptor: sordera, problemas de visión."],["w2zn73","Barreras psicológicas: ejemplos","Emociones como el miedo, la tristeza o la ira; estrés que lleva a una comunicación excesivamente agresiva."],["5alb9","Los dos grandes antídotos contra las barreras de la comunicación","La empatía y la asertividad."],["7z944b","Empatía en el manual","Participación afectiva en la realidad que afecta a otro; ponerse en el lugar del otro, respetar sus derechos, atribuir una intención razonable a su conducta."],["zxpxmx","Asertividad en el manual","Capacidad de comunicar sentimientos y necesidades sin herir ni ofender a los demás; de decir «no» y defender la propia posición sin atacar a la otra parte."],["r5fn2w","Tres formas básicas de reaccionar ante una situación (figura del manual)","Pasividad, asertividad, agresividad."],["1pifuuf","Pasividad en la figura del manual","Pensar que los demás tienen más derechos que nosotros; no expresar nuestras ideas y sentimientos con honestidad, de modo que los demás prevalecen."],["59hgm1","Agresividad en la figura del manual","Defender los propios derechos y expresar los pensamientos de forma deshonesta, normalmente inadecuada, que no respeta los derechos del otro."],["1sd06oc","Según Allan Pease, ¿qué tres recursos usamos para transmitir un mensaje?","Lenguaje verbal (palabras), lenguaje no verbal (gestos, posturas) y lenguaje paraverbal (volumen, tono de voz)."],["r1s31q","Pease: proporción de la comunicación debida al lenguaje no verbal, y con el paraverbal añadido","Más del 50 % para el no verbal; el 80 % si se suma el paraverbal."],["3ierpe","Enumera las seis emociones básicas del manual.","Tristeza, asco, sorpresa, ira, alegría, miedo."],["57yrmk","Lado positivo del miedo según el manual","Nos hace más responsables y cautelosos; el lado negativo es que puede paralizarnos."],["m6ddly","Fatiga: ¿se puede evitar por medios naturales?","No: es un mecanismo biológico que no se puede suprimir de forma natural y que empuja a la persona a descansar."],["b3r3bd","¿Por qué el trabajo nocturno es inherente a la profesión de controlador (CTA)?","Porque muchas dependencias funcionan H24 y el personal rota por turnos que incluyen noches; la noche se diferencia en el entorno (falta de luz, menos tráfico) y en la fisiología."],["1394tun","Además de los factores circadianos, ¿qué otro factor inductor de fatiga nombra el manual?","La carga de trabajo mental sostenida, que puede combinarse con los factores circadianos, el estrés y los factores personales."],["11oqrk2","Sueño medio recomendado para adultos de 18 a 64 años (OMS, National Sleep Foundation)","8 horas al día."],["1fykdej","Dos tipos de sueño en el manual","No REM (sueño lento; cuatro fases) y REM (movimientos oculares rápidos, *Rapid Eye Movements*)."],["vtq2hf","¿Cuántas fases de sueño hay en total y cuánto dura un ciclo de sueño?","Cinco fases (cuatro no REM + REM); un nuevo ciclo aproximadamente cada 90/100 minutos, y los últimos 20 o 30 minutos son REM."],["16nk31m","Fase de sueño I","Sueño ligero; se siguen percibiendo la mayoría de los estímulos; disminuye el tono muscular; movimientos oculares lentos; poco o ningún valor reparador."],["9y5zbt","Fase de sueño II","El sistema nervioso bloquea la entrada sensorial; ocupa el 50 % del tiempo de sueño de un adulto; tono muscular menor; sin movimientos oculares; parcialmente reparador."],["1hxre9c","Fase de sueño III","Sueño «delta» más profundo; despertar provoca confusión y desorientación; sin sueños; la presión arterial y la frecuencia respiratoria bajan un 10-30 %; aumenta la producción de hormona del crecimiento."],["gvw1o4","Fase de sueño IV","Sueño más profundo, actividad cerebral más lenta (delta); esencial para la recuperación física y, sobre todo, psíquica; los déficits de III y IV causan somnolencia diurna."],["virtbl","Sueño REM en el manual","Sueños narrativos; actividad eléctrica cerebral rápida; atonía muscular (parálisis) que impide representar los sueños."],["nx3sh1","Factores que empeoran la calidad del sueño (manual)","Envejecimiento, síntomas de trastornos del sueño (p. ej., apnea), entorno (iluminación, temperatura), cafeína, alcohol, nicotina."],["1bwtenz","Según los estudios citados, ¿cómo es el sueño de los controladores durante el turno de noche en el trabajo?","Más ligero y a menudo interrumpido (no REM), no comparable al sueño en casa."],["1mhjskb","Deuda de sueño","Restricción del sueño que, si se prolonga varias noches, se acumula y reduce progresivamente la atención y la capacidad de trabajo; la recuperación requiere más descanso que una noche normal."],["11elygf","Microsueño","Unos segundos en los que el cerebro se desconecta y la persona se queda dormida, posiblemente sin darse cuenta, perdiendo la conexión con los estímulos externos."],["123wm1f","Riesgos para la salud de la privación continuada de sueño (manual)","Obesidad, diabetes de tipo 2, enfermedades cardiovasculares."],["1txz1fq","Tres procesos que regulan el sueño y la vigilia (manual 5.4)","Circadiano (C), homeostático (S) y de vigilia (W)."],["tzxow1","Proceso circadiano (C)","Reloj biológico interno con un patrón de unas 24 horas que regula la temperatura, las hormonas, etc.; menor actividad aprox. entre las 3 y las 6 h."],["8n53d8","WOCL","*Window Of Circadian Low* (mínimo de la ventana circadiana): coincide con la temperatura corporal basal mínima; mayor somnolencia y menor rendimiento."],["15iabb4","Proceso homeostático (S)","Impulso de dormir que crece con el tiempo de vigilia; sincronizado con C en el trabajo diurno normal, desincronizado en el trabajo nocturno."],["mo5d54","Proceso de vigilia (W)","Inercia del sueño: estado de transición tras despertar con rendimiento reducido; conviene dejar un tiempo prudencial antes de tareas exigentes."],["cqwo1z","¿Qué documento de la OACI (2016) define la fatiga en el manual?","El Doc. 9966, *Manual para la supervisión de los enfoques de gestión de la fatiga*."],["o38yb0","Definición de fatiga del Doc. 9966 de la OACI","Estado fisiológico caracterizado por una reducción de la capacidad de desempeño mental o físico debida a la falta de sueño, a periodos prolongados de vigilia, a la fase circadiana y/o a la carga de trabajo, que puede menoscabar el estado de alerta y la capacidad de desempeñar funciones relacionadas con la seguridad."],["7sk2n2","Aspectos que normalmente se relacionan con la carga de trabajo, ya que no tiene una definición universal","Tipo y naturaleza del trabajo (duración, dificultad, complejidad); limitaciones de tiempo; factores de la capacidad de desempeño individual (experiencia, formación, esfuerzo, historial de sueño, fase circadiana)."],["d3n3dy","¿En qué nivel de carga de trabajo es mejor el rendimiento, según los estudios del manual?","En niveles medios de carga de trabajo."],["q8khsz","Consecuencias de una activación baja con un rendimiento inferior al requerido","Pérdida de información, acciones omitidas, menor vigilancia, rastreo insuficiente, errores, reacción más lenta ante los cambios."],["1rxytks","Consecuencias de una activación demasiado alta","Más errores, decisiones más difíciles, mayor tiempo de reacción, menor atención y concentración, información omitida, incapacidad para evaluar el riesgo y fijar prioridades."],["qjzhys","¿Qué reglamento (de 29 de junio de 2015) enumera los sucesos de notificación obligatoria y trata la fatiga?","El Reglamento de Ejecución (UE) 2015/1018 de la Comisión, anexo III (servicios e instalaciones de navegación aérea)."],["f0uur7","¿Qué fatiga hay que notificar según el anexo III del 2015/1018 (cita del manual)?","La fatiga que afecte, o pueda afectar, a la capacidad de desempeñar con seguridad las funciones de navegación aérea o de tránsito aéreo."],["ixe5kc","Se gestione como se gestione la fatiga, ¿qué son los informes de fatiga?","Una fuente de información esencial, tanto si se gestiona mediante un FRMS como mediante límites prescriptivos."],["1r1qmb9","¿Cuál es el sistema integrado de ENAIRE para la gestión de riesgos de fatiga y estrés?","El FSRMS, *Fatigue and Stress Risk Management System*."],["1rmz4lz","Fatiga frente a cansancio","El cansancio es el elemento subjetivo; la fatiga es objetiva, un estado fisiológico que muestra una capacidad de trabajo reducida."],["zca6ga","Tres tipos de fatiga que nombra el manual","Fatiga mental, visual y física."],["1ex529y","Síntomas psicológicos de la fatiga (manual)","Capacidad cognitiva alterada; memoria afectada; capacidad de planificar/ejecutar alterada; estado de ánimo alterado; irritabilidad; percepción del riesgo alterada."],["1jb3j2a","Síntomas fisiológicos de la fatiga (manual)","Dificultad para enfocar/visión borrosa; irritación, dolor o picor en los ojos; lagrimeo; ojos rojos; dolores de cabeza, confusión o mareos; trastornos relacionados con el sueño."],["132dco1","Figura 9: ¿qué ocurre si el controlador no es consciente de su fatiga?","Puede producirse un incidente de seguridad; si es consciente, se aplican estrategias de primer nivel (prevenir o reducir la fatiga: siesta, cafeína) y de segundo nivel (mitigar sus efectos)."],["17uotcp","Rasgos que distinguen al ATC de otras industrias (manual 5.7)","La seguridad es siempre crítica; muchas dependencias necesitan servicio H24; complejidad y dinamismo muy elevados; escenario de trabajo variable; las personas deben mantener un alto rendimiento."],["zgl46h","Tres grupos de aspectos afectados por el trabajo a turnos","Trastornos del sueño; problemas de salud física y psicológica; dificultades en la vida familiar y social."],["1gfmvg7","¿Qué sueño es «verdaderamente reparador» según el manual?","El sueño nocturno (su ausencia produce fatiga crónica)."],["1aa4iym","¿De qué diferencias individuales depende la tolerancia al trabajo a turnos?","Edad, sexo, condición física, flexibilidad para conciliar el sueño y capacidad para superar la somnolencia."],["zmzcnp","Efectos objetivos de los horarios no circadianos en los controladores (manual)","Menor alerta y atención; mayores tiempos de reacción y decisión; pérdida de memoria a corto plazo; errores de cálculo; menor rendimiento operativo."],["1tsmqe0","Definición de estrés en el manual","Respuesta psicofisiológica a un estímulo interno o externo que surge cuando el organismo interpreta que sus recursos son insuficientes para adaptarse a él."],["1o2ipjl","Tres componentes de respuesta del estrés (tabla del manual)","Endocrino, autónomo, conductual."],["1ttlorr","Estrés agudo frente a estrés crónico (manual)","Agudo: debido a factores que provocan estrés en una ocasión concreta. Crónico: resultado de presiones mantenidas durante mucho tiempo, normalmente emocionales."],["1idax0o","Eustrés frente a distrés según Lazarus y Folkman","Eustrés si la persona espera poder manejar el estímulo; distrés si no."],["c3gt81","¿Qué modelo tiene en cuenta la demanda, la capacidad real y la autopercepción de la persona?","El modelo transaccional del estrés de Cox-Mackay (fuente: EUROCONTROL, «Managing Stress in ATM»)."],["pet5g5","Modelo de Cox-Mackay: ¿qué produce el estrés?","El desequilibrio que se encuentra en la valoración cognitiva entre la demanda percibida y la capacidad percibida (la demanda y la capacidad reales alimentan las percibidas)."],["tkan82","Síntomas fisiológicos del estrés (manual)","Cardiovasculares (palpitaciones, tensión arterial alta, frecuencia cardiaca), respiratorios, sudoración, del sueño, gastrointestinales, musculares, psicosomáticos, dolores de cabeza y migrañas."],["1g3kxbl","Síntomas conductuales del estrés (manual)","Problemas de autocontrol, confianza o autoestima; automedicación, alcohol o drogas; fatiga y problemas de sueño; absentismo; aislamiento social; deterioro del desempeño laboral."],["1aoa93u","Síntomas cognitivos del estrés (manual)","Atención, vigilancia y alerta afectadas; capacidad de planificar/ejecutar afectada; acciones no deliberadas (activación involuntaria de funciones)."],["1qr0khw","Nombra seis habilidades requeridas en ATC (manual 6.3).","Por ejemplo: habilidades visoespaciales, percepción, procesamiento de la información, reconocimiento de imágenes y patrones, priorización, resolución lógica de problemas, reglas y procedimientos, toma de decisiones, comunicación interpersonal, trabajo en equipo, vocabulario técnico."],["1v1mg9a","Los cuatro estados de estrés relacionados con las tareas de control","Hipoestrés, eustrés, hiperestrés, distrés."],["d60edb","Hipoestrés en ATC","Aburrimiento o tarea rutinaria: poco interés y tensión; mal rendimiento y alta probabilidad de error."],["1ub9550","Eustrés en ATC","Tarea más interesante o urgente: tensión positiva; la zona de mejor rendimiento sin que la presión desborde."],["t9vt7x","Hiperestrés en ATC","Sobrecarga de tareas o conflicto muy elevado: pérdida de control, ansiedad, distracciones, decisiones retrasadas; «por detrás del tráfico»; atención centrada en las señales centrales o más frecuentes."],["1n7ertj","Distrés en ATC (manual 6.3)","Los procedimientos usados para controlar son nuevos y aún no resultan familiares; la calidad de la gestión de conflictos se resiente."],["wig6x6","Límite de la memoria de trabajo que se da en el párrafo del hiperestrés","No puede manejar más de seis o siete elementos."],["f0t6om","¿Qué texto de la EASA distingue tres fuentes principales de estrés en ATC?","GM1 ATS.OR.310 Estrés (Reglamento 2017/373)."],["1m1s0cn","Tres fuentes principales de estrés en ATC (EASA)","Factores estresantes ambientales/físicos, relacionados con la tarea e individuales."],["1jrlh19","Factores estresantes ambientales/físicos: ejemplos","Hambre, dolor, falta de sueño; contaminación acústica, calor; en la sala de operaciones: temperatura, espacio de trabajo incómodo, calidad del aire, iluminación, ruido o vibración intrusivos."],["1d9yjkj","El estrés depende de la intensidad y ¿de qué más?","De la duración de la exposición (un ruido agudo persistente puede estresar tanto como uno fuerte y repentino)."],["1lm9aon","Factores estresantes relacionados con la tarea (ejemplos)","Carga de trabajo alta sostenida; tráfico heterogéneo; equipos poco fiables; procedimientos imprecisos; equipos complejos; supervisión de alumnos; desajuste entre carga de trabajo y habilidades; ambigüedad de roles; conflictos interpersonales; situaciones inusuales, incidentes, emergencias."],["1hj88pt","Factores estresantes individuales: ¿cuál es el «mito» que se menciona?","La creencia de que los factores estresantes personales se pueden dejar en casa."],["mhgenc","Ejemplos de grandes acontecimientos vitales que actúan como factores estresantes (manual)","Muerte de un ser querido, nacimientos, matrimonio, divorcio."],["gnmcn9","Factores estresantes que reconocen los controladores en los estudios (varios)","Fallo de equipos, tráfico muy elevado, miedo a causar accidentes, falta de tiempo o de conocimientos, incertidumbre, cambios en los procedimientos, evaluación continua de la competencia, incertidumbre profesional, trabajo a turnos, cuestiones laborales."],["jg3cmy","¿Qué tres funciones del controlador perjudica un estrés elevado?","La percepción, la conciencia situacional y la toma de decisiones."],["1iiwsru","Efectos del estrés en el desempeño del controlador (nombra cinco).","Problemas de concentración; errores y omisiones; «el camino más rápido/fácil»; traspasar responsabilidad a otros; fijación mental; posponer decisiones; no tener plan B; asumir más riesgos; precipitación por la adrenalina; usar procedimientos no operativos, olvidar la fraseología, usar la lengua materna."],["1gld60l","Bajo un estrés significativo, ¿qué idioma y qué fraseología puede usar el controlador?","Su lengua materna, olvidando la fraseología normalizada, y puede usar procedimientos que ya no están operativos."],["1otxu1z","Medidas de mitigación del estrés que sugiere la normativa europea (manual)","Política de estrés y programa CISM; vigilancia proactiva; mitigación del impacto operativo; formación/información; mecanismos si el estrés impide tareas críticas; actividades que mitiguen el estrés."],["dry4dk","CISM significa","*Critical Incident Stress Management* (gestión del estrés por incidente crítico)."],["1pzbk2r","Finalidad del programa CISM","Apoyo psicológico al personal operativo para evitar reacciones de estrés postraumático derivadas de un incidente crítico."],["1qklsve","Tres rasgos clave del CISM","Confidencial, voluntario y educativo; se conoce como «primeros auxilios psicológicos»."],["1uo19o8","Definición de incidente crítico","Un suceso que ocurre de forma repentina o inesperada y tiene potencial para crear una angustia grave, causando malestar o incapacidad para desempeñar las funciones en ese momento o más tarde."],["173wo1b","Ejemplos de incidentes críticos en ATC (nombra cinco).","Accidentes; desastres devastadores; gestión de una aeronave en emergencia; sucesos con resultado de muerte; vulneraciones de la separación mínima; muerte de familiares o compañeros; incidentes evitados por poco (*near-incidents*); violencia; actos delictivos, agresiones o amenazas."],["zjlypq","¿En qué modelo se basa el programa CISM de ENAIRE?","El modelo de *peers* (controladores de apoyo)."],["11nezes","¿Qué es un *peer* en el CISM?","Un controlador de apoyo específicamente formado para dar apoyo psicológico a otros controladores tras un incidente crítico (complementado con ayuda psicológica profesional cuando hace falta)."],["1pt0na5","¿Qué normas se siguen para formar a los *peers*?","Las de la International Critical Incident Stress Foundation (ICISF)."],["atwcuq","Tareas principales de los *peers* (tres)","Intervención inmediata en la crisis; asesoramiento psicológico a los compañeros afectados; organizar apoyo profesional de salud mental cuando es necesario."],["1l08eyh","¿Quién puede ser *peer*?","Controladores voluntarios con amplia experiencia profesional, específicamente seleccionados y formados."],["xdadqf","Perfil del *peer*: ¿qué debe saber sobre los límites del CISM?","Que su trabajo es prestar primeros auxilios, no atención psicológica profesional."],["14hpv66","¿Qué documento de EUROCONTROL fija los requisitos de selección de *peers* de ENAIRE?","*Human Factors - Critical Incident Stress Management: User Implementation Guidelines*, 2008, edición 2.0."],["pkpuz2","Las cinco fases del CISM (en orden)","1 Comunicación y difusión; 2 selección y formación de *peers* y grupos de interés; 3 intervención de los *peers*; 4 derivación a un profesional médico cuando proceda; 5 evaluación periódica del programa."],["112rgmi","¿Cómo se evalúa el programa CISM y qué se registra?","Mediante cuestionarios totalmente anónimos a los usuarios; un informe anual del CISM; estadísticas de activaciones frente a incidentes y de cuántos necesitaron psicólogos profesionales."],["1i6uz7n","Error humano: ¿es evitable?","Inevitable y también necesario para promover el aprendizaje; no se puede eliminar del todo, pero pueden identificarse los contextos que lo facilitan."],["jdvl4m","Definición operativa de error en el manual","Situación en la que una secuencia planificada de acciones no logra alcanzar el objetivo."],["15po38o","En el sistema ATC, «error» se refiere a","Toda la organización, no solo a los fallos de los controladores."],["qhyfjl","GEMS: ¿cómo se clasifican primero los errores?","Como consecuencia de una conducta intencionada o no intencionada, y luego se subdividen en deslices, lapsus y equivocaciones."],["loeoh2","GEMS, desliz (*slip*): definición y proceso cognitivo","Acción no intencionada por un fallo o laguna de atención: omisión, inversión o alteración del orden o del momento; procesos atencionales."],["188r1ns","GEMS, lapsus (*lapse*): definición y proceso cognitivo","Acción no intencionada por un fallo de memoria (olvidar una intención u omitir aspectos planificados); procesos mnemónicos y gestión de la memoria de trabajo."],["2unlb8","GEMS, equivocación (*mistake*): definición y proceso cognitivo","Acción intencionada por un error de planificación: aplicación incorrecta de una regla correcta, o regla correcta en una situación inadecuada; procesos de SA y de toma de decisiones."],["w313g8","¿Qué tipo de error GEMS es el más frecuente?","Los lapsus."],["w6655n","¿Qué tipos de error GEMS son en esencia respuestas automáticas sin decisión consciente?","Los deslices y los lapsus."],["1ou2wvu","¿Cómo se mitigan los deslices (manual)?","Formación procedimental, entrenamiento atencional, monitorización mutua, procedimientos y listas de comprobación."],["pm7wlo","¿Cómo se mitigan los lapsus (manual)?","Actualización frecuente de la información y ayudas cognitivas externas (notas en la etiqueta de la tira o en papel)."],["1n3o78m","¿De qué tipo de error es ejemplo el fallo de la memoria prospectiva?","De un lapsus."],["x233fe","¿Cómo se mitigan las equivocaciones (manual)?","Mediante procedimientos y normalización de los métodos, y mediante la actitud del profesional, consciente de su vulnerabilidad a los sesgos."],["op7j2p","Tres sesgos cognitivos que el manual nombra para las equivocaciones","Sesgo de continuidad de plan, sesgo de expectativa, sesgo de familiaridad."],["1aurbza","¿Dónde se originan los sesgos cognitivos?","En procesos mentales heurísticos que generan reglas rápidas del tipo «si A, entonces B»."],["ek1dn6","Cuatro grandes familias de sesgos cognitivos (manual)","Los que deciden qué debo recordar; los que filtran la información cuando hay demasiada; los que aparecen cuando necesito actuar rápido; los que surgen cuando la información carece de suficiente significado."],["y1o5fj","TEM (gestión de amenazas y errores): ¿qué organismo desarrolló el concepto?","La OACI (referencia del manual: Circular 314, 2005)."],["1m2ly7z","TEM: ¿cuál es su análisis clave?","Las acciones u omisiones que generan un estado inseguro (no deseado) que no acaba en un suceso, para detectar y captar los errores como mecanismo para crear seguridad."],["1g5j4sw","Secuencia de la figura TEM (modelo de la OACI)","Amenazas, estrategias, errores, resistir/resolver, consecuencia."],["mm3yop","Amenazas TEM","Errores o incidentes externos que aumentan la complejidad y ocurren sin que el controlador los haya causado (indicativos parecidos, procedimientos locales no estándar, restricciones del espacio aéreo, meteorología adversa, congestión, contingencias)."],["pc16vv","TEM: amenazas previsibles frente a imprevistas","Previsibles: el controlador puede anticiparlas (p. ej., meteorología adversa). Imprevistas: aparecen de forma inesperada (p. ej., un piloto copia instrucciones dadas a otra aeronave)."],["1l33wjn","Premisa del TEM sobre errores y amenazas","No pueden eliminarse, por lo que se necesitan estrategias para afrontarlos; la relación amenaza-error-estado no deseado no siempre es directa ni lineal."],["2bw6ln","Errores TEM","Decisiones u omisiones del controlador que hacen que no se cumplan los objetivos planificados y se comprometan los márgenes de seguridad; pueden ser espontáneos, estar ligados a amenazas o formar parte de una cadena de errores."],["cnzy7v","Estados no deseados TEM","Situaciones en las que la planificación ha fallado y los límites de seguridad se reducen (p. ej., una aeronave que asciende a un nivel de vuelo no autorizado o vira a un rumbo no planificado)."],["xeyzmq","Estado no deseado frente a consecuencia","En un estado no deseado la situación aún se puede resolver; una vez se produce una consecuencia ya no hay vuelta atrás."],["i6ev33","Según el manual, ¿qué es implícitamente el control de tránsito aéreo?","La detección de estados no deseados, tanto naturales por la evolución del tráfico como generados por la acción del ATC."],["1q3l1wb","Fecha del manual","«Elaborado: noviembre 2026», 65 páginas, © 2026 ENAIRE (mismo contenido y paginación que la edición de julio de 2023, salvo la corrección de la p. 35)."],["s8bb60","Figura 1 del modelo de Reason: ¿qué cinco bloques aparecen de izquierda a derecha?","Organización (decisiones de gestión y procesos institucionales), lugar de trabajo (condiciones de trabajo), personas (errores e infracciones), defensas y accidente."],["gbevcc","Figura 1 del modelo de Reason: ¿qué tres defensas aparecen?","Tecnología, capacitación y reglamentos."],["1g9ga6o","Figura 1 del modelo de Reason: ¿qué une directamente la organización con las defensas?","La trayectoria de las condiciones latentes."],["skhjhd","Figura 2 del manual: ¿cómo se dibuja el modelo SHELL-O?","La L en el centro, rodeada de H (arriba), S (izquierda), E (derecha) y otra L (abajo); un círculo O envuelve el conjunto."],["1qdkcp","Según el manual (1.3), ¿por qué fueron tan importantes los trabajos de Reason y Rasmussen?","Porque aportaron una visión científica sobre las actuaciones que fallan, con el error despojado de juicios de valor."],["1sghu8c","Safety-II: reconocer e investigar cómo afronta el individuo sus continuas adaptaciones diarias, ¿qué permite comprender?","Cómo se desarrolla la competencia profesional."],["18q7sf0","Figura 4 (EUROCONTROL/FAA 2010): ¿qué tres estrategias de integración de los FFHH en la gestión de proyectos compara?","a) Sin integración de los FFHH; b) integración reactiva; c) integración proactiva."],["dsfzd5","Figura 4: ¿qué estrategia tiene el coste más alto en el diseño y el más bajo en la operación?","La integración proactiva de los FFHH."],["10wcxmi","Figura 4: ¿qué estrategia acaba con el mayor coste de detectar y resolver problemas de actuación humana en la operación?","No integrar los FFHH (la reactiva queda en un nivel intermedio)."],["fbr3os","Figura 4: ¿qué fases del ciclo de vida aparecen en el eje horizontal?","Diseño, implementación y operación."],["14k420n","Según el manual (1.6), ¿qué debe fijar como prioridad una organización respecto a los proyectos tecnológicos ATM?","La sistematización de la integración de los FFHH en el desarrollo e implementación de todos los proyectos tecnológicos."],["1wl70s1","¿Con qué horizonte tendrán impacto las mayores exigencias de la normativa europea sobre la gestión del factor humano (manual 1.6)?","A medio y largo plazo."],["171lh6a","Figura 5 (Endsley): factores de la tarea y del entorno","Carga de trabajo, estresores, diseño del sistema y complejidad."],["6mc4xj","Figura 5 (Endsley): factores individuales","Objetivos, ideas preconcebidas, conocimiento, experiencia, formación y habilidades."],["1awt1b","Figura 5 (Endsley): ¿qué sigue a la conciencia situacional en la cadena del modelo?","La decisión y después la ejecución de la acción, que modifica el estado del entorno/sistema y realimenta la SA."],["z6sbwy","Figura 6 (Isaac y Ruitenberg, 1997): ¿cuántos elementos influyen en la SA del controlador y cuáles son?","Once: centros adyacentes, factores personales, meteorología, infraestructura del aeropuerto, compañeros, tráfico, operadores y pilotos, entorno, radioayudas, actuaciones de la aeronave y equipos."],["64empw","Figura 6: aspectos del elemento «factores personales»","Confort físico, estrés y fatiga."],["18ucru","Figura 6: aspectos del elemento «compañeros»","Puntos fuertes y débiles, nivel de rendimiento, gradiente social y formación en curso."],["2fb6ms","Figura 6: aspectos del elemento «tráfico»","Situación («la imagen»), evolución, patrones y flujo."],["u9u2dg","Figura 6: aspectos del elemento «infraestructura del aeropuerto»","Pistas disponibles, obras en curso y ayudas visuales (iluminación, señales)."],["12h9rba","Figura 6: aspectos del elemento «operadores y pilotos»","Nivel de familiaridad, nivel de rendimiento y nivel de radiotelefonía (incluido el vocabulario)."],["khhjye","Figura 6: aspectos del elemento «entorno»","Obstáculos, características del terreno y sensibilidad al ruido."],["1gwt3kx","Figura 6: aspectos del elemento «meteorología»","Actual, prevista y especial (cizalladura, vientos en altura)."],["gp5qmy","Figura 6: aspectos de «equipos» y de «radioayudas»","Equipos: disponibilidad, fiabilidad, rendimiento, degradaciones. Radioayudas: disponibilidad y nivel de rendimiento."],["les499","Figura 6: aspectos de «centros adyacentes» y de «actuaciones de la aeronave»","Centros adyacentes: nivel de rendimiento, limitaciones, capacidad. Actuaciones de la aeronave: diferencias, degradaciones, posibilidades y limitaciones."],["1omg5ux","¿Qué año da el pie de la figura 6 para Isaac y Ruitenberg, y cuál la bibliografía del manual?","El pie de la figura, 1997; la bibliografía, 1999 (*Air Traffic Control: Human Performance Factors*)."],["4qd68v","Figura 7 (Yerkes-Dodson según la complejidad): ¿cómo es la curva de la tarea compleja frente a la de la sencilla?","Queda por debajo y su pico (activación óptima) llega antes, con menos activación."],["eiw9bq","Figura 8 (Yerkes-Dodson): ¿qué rótulos llevan los tramos ascendente y descendente de la curva?","Ascendente: atención e interés crecientes. Descendente: rendimiento deteriorado por una ansiedad intensa. Cima: activación y rendimiento óptimos."],["1n0no08","¿En qué marco sitúa el manual la definición de carga de trabajo mental (3.3)?","En un marco de factores de estrés que interactúan en el individuo y que, por tanto, influyen en el rendimiento humano."],["xvzf71","Escucha activa: además de entender una situación, ¿qué consigue según el manual (4.1)?","Que el otro se relaje o se sienta comprendido y tender un puente hacia él cuando cuesta entenderse; es la mejor manera de conectar emocionalmente."],["rsjz3i","Gráfico de la p. 34: nombra cinco beneficios de la escucha activa.","Clima de confianza y cercanía; comunicar aceptación e incrementar la motivación; estimular la cooperación; reducir la tensión y las diferencias de criterios; ganar tiempo para pensar; aprender del otro; aprender a trabajar mejor; tomar mejores decisiones con mayor seguridad; reducir los conflictos."],["nvbwl2","Barreras semánticas (manual, edición de noviembre de 2026)","El emisor utiliza palabras con un significado, pero el receptor lo interpreta de manera diferente."],["1cdacpr","Según el recuadro de la p. 38, ¿qué lenguaje es el de las emociones y cuál el de la lógica?","El no verbal y el paraverbal son el lenguaje de las emociones; las palabras, el de la lógica."],["gpdbrc","¿Cuándo pasa a ser predominante el lenguaje no verbal y paraverbal (manual, p. 38)?","Cuando aparecen las emociones (cansancio, estrés, presión de tiempos, conflictos); sin ningún conflicto, las palabras bastan."],["w5y5xo","Tristeza según el manual","No ayuda dejarse llevar por ella; al superarla se asume una pérdida o se toma conciencia de una situación."],["dhfy4s","Asco y sorpresa según el manual","Asco: adaptativamente positiva, ayuda a rechazar algo que no es bueno para la salud. Sorpresa: ayuda a reconocer novedades, siempre que no lleve al sobresalto constante."],["11yiwgd","Ira y alegría según el manual","Ira: mal manejada es una pérdida de energía; bien manejada lleva a rebelarse contra una situación no deseada y da fuerzas para afrontarla. Alegría: necesaria para «recargar» las pilas y facilitar la interacción."],["17egio5","Gestión de los riesgos del estrés: ¿qué oportunidad ofrece según el manual (6.4)?","Maximizar el bienestar del personal ATM, con el propósito final de mejorar la seguridad y la eficiencia."],["cl2zf8","TEM como herramienta de análisis de riesgos: ¿qué es tan importante como analizar los errores y amenazas potenciales?","Estudiar las circunstancias (estados) no deseadas que se pueden crear en el desarrollo de las operaciones."],["jltfdj","Reglamento 2017/373: ¿qué fecha da el manual como entrada en vigor, y qué es realmente esa fecha?","El 02/01/2020; según el art. 10 del Reglamento es la fecha desde la que es aplicable (entró en vigor a los veinte días de su publicación en el DOUE)."]]);
